<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$error='';$edit=null;$editId=(int)($_GET['edit']??0);if($editId){$s=$pdo->prepare('SELECT * FROM lessons WHERE id=?');$s->execute([$editId]);$edit=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';try{if($action==='delete'){$s=$pdo->prepare('DELETE FROM lessons WHERE id=?');$s->execute([(int)$_POST['id']]);flash('success','Lesson deleted.');redirect('admin/lessons.php');}$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$slug=trim($_POST['slug']??'');$level=$_POST['level']??'beginner';$description=trim($_POST['description']??'');$content=trim($_POST['content']??'');$minutes=max(1,(int)($_POST['estimated_minutes']??10));$published=isset($_POST['is_published'])?1:0;if($title===''||$content==='')throw new RuntimeException('Lesson title and lesson content are required.');if(!in_array($level,['beginner','elementary','intermediate'],true))$level='beginner';if($slug==='')$slug=strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$title)),'-'));if($id){$s=$pdo->prepare('UPDATE lessons SET title=?,slug=?,level=?,description=?,content=?,estimated_minutes=?,is_published=? WHERE id=?');$s->execute([$title,$slug,$level,$description,$content,$minutes,$published,$id]);}else{$s=$pdo->prepare('INSERT INTO lessons(title,slug,level,description,content,estimated_minutes,is_published) VALUES(?,?,?,?,?,?,?)');$s->execute([$title,$slug,$level,$description,$content,$minutes,$published]);}flash('success','Lesson saved successfully.');redirect('admin/lessons.php');}catch(Throwable $e){$error=$e->getMessage();}}
$lessons=$pdo->query('SELECT id,title,level,is_published,updated_at FROM lessons ORDER BY sort_order,id DESC')->fetchAll();$page_title='Manage lessons';require __DIR__.'/../includes/admin_header.php';$v=$edit??$_POST;
?>
<div class="admin-heading"><div><span class="eyebrow">CONTENT</span><h1>Manage lessons</h1><p>Create and maintain the structured Somali learning path.</p></div></div><div class="admin-two-col"><section class="admin-panel"><div class="panel-heading"><h2><?= $edit?'Edit lesson':'Add a lesson' ?></h2><?php if($edit): ?><a href="<?= url('admin/lessons.php') ?>">Cancel</a><?php endif; ?></div><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="admin-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($v['id']??0) ?>"><label>Lesson title<input name="title" required value="<?= e($v['title']??'') ?>"></label><label>URL slug (optional)<input name="slug" value="<?= e($v['slug']??'') ?>" placeholder="greetings-and-introductions"></label><div class="form-row"><label>Level<select name="level"><?php foreach(['beginner','elementary','intermediate'] as $level): ?><option value="<?= $level ?>" <?= ($v['level']??'beginner')===$level?'selected':'' ?>><?= e(level_label($level)) ?></option><?php endforeach; ?></select></label><label>Estimated minutes<input type="number" min="1" name="estimated_minutes" value="<?= (int)($v['estimated_minutes']??10) ?>"></label></div><label>Short description<textarea name="description" rows="2"><?= e($v['description']??'') ?></textarea></label><label>Lesson content<textarea name="content" rows="9" required placeholder="Write the lesson explanation, examples and practice notes here."><?= e($v['content']??'') ?></textarea></label><label class="check-label"><input type="checkbox" name="is_published" value="1" <?= !isset($v['is_published'])||$v['is_published']?'checked':'' ?>> Publish this lesson</label><button class="btn btn-primary" name="action" value="save">Save lesson</button></form></section><section class="admin-panel"><div class="panel-heading"><h2>Existing lessons</h2><span><?= count($lessons) ?> total</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Lesson</th><th>Level</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($lessons as $l): ?><tr><td><strong><?= e($l['title']) ?></strong></td><td><?= e(level_label($l['level'])) ?></td><td><span class="admin-status <?= $l['is_published']?'published':'draft' ?>"><?= $l['is_published']?'Published':'Draft' ?></span></td><td><a href="?edit=<?= (int)$l['id'] ?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this lesson and its quiz questions?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><button name="action" value="delete" class="link-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
